#include <memory>
#include <iostream>

// NOTE: Requires C++03 or C++11/14 with deprecation warnings
void transfer_ownership(std::auto_ptr<int> p) {
    // p now owns the resource
    std::cout << "Inside function.\n";
}

int main() {
    std::auto_ptr<int> original(new int(42));

    // 1. Copy Construction: Transfers ownership
    std::auto_ptr<int> copy = original; 

    // original is now nullified
    if (original.get() == nullptr) {
        std::cout << "Original is null after copy.\n";
    }

    // 2. Pass by Value: Transfers ownership
    std::auto_ptr<int> source(new int(100));
    transfer_ownership(source); // Source is nullified here

    if (source.get() == nullptr) {
        std::cout << "Source is null after function call.\n";
    }
}
